INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bench_tender', 'uk', 'Тендер на скамейкі', 'Подрядчік предлагает откатіть за победу в тендере на «золотые» скамейкі для парка. Дружіна тем временем намекает на алевый пентхаус.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('tama_38', 'uk', 'Махінаціі с ТАМА 38', 'Застройщік просіт закріті глаза на трі «лішніх» этажа в проекте ТАМА 38 в центре міста. Обещает занесті солідную сумму в швейцарскій банк.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shelters_budget', 'uk', 'Бюджет на мамады (Бомбоубежіща)', 'Государство выделіло огромный бюджет на ремонт старых бомбоубежіщ. Брат жены внезапале открыл фірму по устаалевке бронірованных дверей.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('state_comptroller', 'uk', 'Проверка Госконтролера', 'В муніціпалітет нагрянула проверка от Мевакер ха-Медіна. Аудіторы требуют доступ к бухгалтеріі за прошлый год.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_blackmail', 'uk', 'Коаліціонный крізіс (Шаббат)', 'Релігіозные партіі угрожают разваліть коаліцію, якщо вы не закроете все паркі і бізнесы в Шаббат. Дружіна дуже любіт гулять по субботам.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lawyer_visit', 'uk', 'Візіт адвоката-решалы', 'Известный адвокат предлагает «потерять» пару непріятных папок на вас в Лахав 433 за солідный гоалерар.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('garbage_extortion', 'uk', 'Рэкет на мусоре', 'Бравые парні із Калансуа прішлі на тендер по вывозу мусора в восточных районах і прозрачале намекнулі, что без іх «крыші» у мусоровозов могут пробіться колеса.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('neighbor_mayor_amuta', 'uk', 'Братская допомога коллеге', 'Мер соседней Хадеры звоніт в паніке: перед выборамі срочале нужна «амута» (некоммерческая організація) для сбора пожертвованій, просіт подбросіть на кампанію.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shitty_burger', 'uk', 'Скандал с White Burger', 'В алевой бургералей *White Burger*, прінадлежащей твоему главалему спонсору, інспекторы нашлі мясо крайне сомнітельалего проісхожденія. Требуют закріті лавочку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_parking', 'uk', 'Субботній парковочный ад', 'Жітелі светскіх райоалев взвылі: по субботам всё заставлеале машінамі так, что скорая не проедет. Оппозіція требует устроіть облаву с эвакуаторамі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('flooded_street', 'uk', 'Потоп на уліце Вайцман', 'Прошел первый серьезный лівень, і центральная вуліця Вайцман уплыла. Бюджет на прочістку лівневок куда-то іспарілся, а местные паблікі уже полощут твое імя.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('burning_trucks', 'uk', 'Горящіе мусоровозы', 'Пара дней молчанія закончілась: алечью на муніціпальалей стоянке сгорелі трі мусоровоза. На асфальте баллончіком напісаале «Прівет із Калансуа». Половіна міста утопает в отходах.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kompromat_retaliation', 'uk', 'Ответный удар СМИ', 'Мер соседней Хадеры не простіл сліва. В крупалем телеграм-канале вышло расследованіе про твою «неучтенную» віллу в Кесаріі і снімкі твоей жены в міланском бутіке.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('arnona_scandal', 'uk', 'Скідкі по Аралене для ізбранных', 'Журналісты выяснілі, что бізнес вашего крупалего спонсора получает 80% скідку на земельный налог (аралену).');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('beach_kiosk', 'uk', 'Захват містоского пляжа', 'Владелец пляжалего ресторана без разрешенія захватіл 200 метров береговой лініі і поставіл платные шезлонгі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('electric_scooters', 'uk', 'Нашествіе электросамокатов', 'Жітелі разгневаны: самокаты бросают на тротуарах, а гонщікі сбівают пенсіонеров.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('stadium_naming', 'uk', 'Права на названіе стадіона', 'Олігарх хоче переімеалевать містоской стадіон в честь своей коммерческой компаніі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('sewage_overflow', 'uk', 'Прорыв каналізаціі', 'Главный коллектор не выдержал нагрузок. Набережная затаплівается нечістотамі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('friday_country_club', 'uk', 'Пятнічные встречі в Кантрі-клубе', 'Каждую пятніцу в 8:00 утра вы сідіте в шезлонге у бассейна Кантрі. К вам выстраівается очередь із знакомых і незнакомцев с «маленькімі просьбамі».');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('country_cctv_raid', 'uk', 'Изъятіе запісей в Кантрі', 'Следователі Лахав 433 явілісь в адміністрацію Кантрі-клуба і требуют серверы с камерамі відеонаблюденія за прошлую пятніцу.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kindergarten_favor', 'uk', 'Блат в детском саду', 'Старый друг прішел к вам в кабінет с просьбой срочале перевесті его ребенка в элітный садік в центре міста, хотя мест давале нет.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('metro_depot', 'uk', 'Строітельство депо метро', 'Міністерство транспорта предлагает построіть гігантское депо метро в черте міста. Подрядчікі в восторге, але мешканці в гневе із-за шума і стройкі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bagrut_success', 'uk', 'Реформа школьалего образованія', 'Городу подвернулся шанс поднять процент сдавшіх Багрут на рекордный уровень, але гордепартамент образованія просіт солідный бюджет на репетіторов і лабораторіі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('park_sculptures', 'uk', 'Современалее іскусство в парке', 'Ваш блізкій друг-скульптор предлагает уставіть центральный містоской парк своімі абстрактнымі статуямі із ржавого железа за счет бюджета.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('yom_haatzmaut', 'uk', 'Праздалеваніе Дня Незавісімості', 'Главалее событіе года! Спонсоры перевелі мілліоны на празднічный концерт, салюты і угощенія. Поліція в цей день празднікі не портіт.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wife_dog_park', 'uk', 'Собака для жены', 'Дружіна хоче собаку, але в районе нет площадкі для выгула.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('cat_exhibition', 'uk', 'Выставка кошек', 'Дружіна познакомілась с местным клубом любітелей кошек і просіт організовать містоскую выставку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_parade', 'uk', 'Парад Гордості на уліце Вайцман', 'Організаторы просят разрешеніе провесті Парад Гордості на центральалей уліце міста. Тема вызвала бурные споры.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_coalition_crisis', 'uk', 'Крізіс в коаліціі', 'Релігіозные партнеры по коаліціі в бешенстве от прошедшего парада і требуют немедленале закріті містоской ЛГБТ-клуб.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_strip_club', 'uk', 'Скандал после встречі меров', 'После ежегодалего съезда меров вы пошлі отмечать в стріп-клуб. Пресса узнала об цем і устроіла вам головомойку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_revenge', 'uk', 'Ответка союза меров', 'Меры соседніх містоов узналі, кто сліл іх фотографіі в стріп-клубе прессе, і решілі объедініться протів вас.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('son_wedding', 'uk', 'Свадьба сіна', 'Ваш сін женітся. Это отлічалее событіе і поворотный момент для всей семьі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wedding_investigation', 'uk', 'Расследованіе по свадьбе', 'Журналісты пронюхалі, что на пышалей свадьбе сіна вам передавалі хабарі под вібудіалек подарков.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_funeral', 'uk', 'Траур і похороны отца', 'В семье stem-трагедія: скончался ваш батько. Время проведенія шівы і пріема соболезалеваній.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_monument_offer', 'uk', 'Памятнік от застройщіков', 'Вліятельные застройщікі, пріходівшіе на шіву, предлагают полалестью оплатіть элітный памятнік вашему отцу.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('daughter_school', 'uk', 'Дочка ідет в школу', 'Формірованіе классов на алевый учебный год. Пора решіть, с кем будет учіться ваша донька.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('school_flood', 'uk', 'Потоп в школе', 'В школе дочері прорвало старые трубы, классы полалестью затоплены.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('apartment_renovation', 'uk', 'Ремонт квартіры', 'Дружіна захотела зробіті ремонт в квартіре. Игрок выбірает между коррупціей, транжірством ілі жесткой экоалеміей.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('renovation_leak', 'uk', 'Слів ремонта от блогера', 'Блогер прознал про бесплатный элітный ремонт от містоского подрядчіка і сліл фото в інтернет.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wife_real_estate', 'uk', 'Недвіжімость за граніцей', 'Дружіна насмотрелась інстаграма і хоче купіті будіалекік в Италіі.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('tiberias_mockery', 'uk', 'Насмешкі: «Мер — лох»', 'Блогер узнал про покупку старой квартіры в Тверіі. Вышла разгромная статья: соседніе меры і поліція смеются над тобой.');
